const item = $input.first().json;
const data = item.body || item;

const category = (data.incident_category || 'ACCIDENT').toUpperCase();
const isBlocked = data.is_road_blocked === true;
const blockage = data.blockage_level || 'PARTIAL_LANE_CLOSURE';
const road = data.road_name || 'Urban Arterial Corridor';
const congestion = data.traffic_impact ? data.traffic_impact.congestion_percentage : 80;
const delay = data.traffic_impact ? data.traffic_impact.estimated_delay_minutes : 25;

let dispatchTeam = 'Traffic Police & Recovery Crane';
let priority = 'EMERGENCY_TIER_1';

if (category.includes('DISASTER') || category.includes('FLOOD') || category.includes('LANDSLIDE')) {
  dispatchTeam = 'Civil Defense & Disaster Response Squad';
  priority = 'CATASTROPHIC_TIER_0';
} else if (category.includes('ACCIDENT')) {
  dispatchTeam = 'Crash Investigation & Heavy Recovery Crane';
  priority = 'CRITICAL_ACCIDENT';
}

return [{
  json: {
    ...data,
    processed_at: new Date().toISOString(),
    assigned_dispatch_unit: dispatchTeam,
    emergency_priority: priority,
    is_road_impassable: isBlocked,
    citizen_broadcast_ready: true,
    summary: `${priority}: ${category} at ${road}. Blockage: ${blockage}. Congestion: ${congestion}% (+${delay}m delay).`
  }
}];
